Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Notation fmem := (word -> option byte).

Definition y4_body_stmt : Prop :=
  forall (Q : machine_state -> Prop) (mm : fmem) (F : bvmap 5 word) (fc : bv 32)
         (sp gp tp a0 s6 s8 t3 : word) (b0 b1 b2 b3 : word) (j6 j9 j13 j19 j20 j21 j29 j30 j31 : word)
         (DT4 DST dcap SS n IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 : Z) (obuf tbl sbuf : list byte),
    mem_inv psegs mm ->
    bytes_at psegs mm DT4 tbl -> Z.of_nat (length tbl) = 8192 -> ztab_fact psegs mm DT4 8192 4 [(2, 0, 11); (3, 1, 2)] ->
    u8arr psegs mm DST obuf -> Z.of_nat (length obuf) = dcap ->
    bytes_at psegs mm SS sbuf -> Z.of_nat (length sbuf) = n ->
    0 < DT4 -> DT4 + 8192 <= 2^47 -> 0 < DST -> DST + dcap <= 2^47 -> 0 < SS -> SS + n <= 2^47 ->
    (DST + dcap <= DT4 \/ DT4 + 8192 <= DST) -> (DST + dcap <= SS \/ SS + n <= DST) ->
    SS + 7 <= IP0 -> IP0 + 8 <= SS + n -> SS + 7 <= IP1 -> IP1 + 8 <= SS + n ->
    SS + 7 <= IP2 -> IP2 + 8 <= SS + n -> SS + 7 <= IP3 -> IP3 + 8 <= SS + n ->
    DST <= OP0 -> OP0 + 10 <= DST + dcap -> DST <= OP1 -> OP1 + 10 <= DST + dcap ->
    DST <= OP2 -> OP2 + 10 <= DST + dcap -> DST <= OP3 -> OP3 + 10 <= DST + dcap ->
    (forall (mm' : fmem) (b0' b1' b2' b3' : word) (nb0 nb1 nb2 nb3 d0 d1 d2 d3 : Z)
            (j6' j9' j13' j19' j20' j21' j29' j30' j31' : word),
       munch [(DST, DST + dcap)] mm mm' -> wmono psegs mm mm' -> mem_inv psegs mm' ->
       (exists obuf', u8arr psegs mm' DST obuf' /\ length obuf' = length obuf) ->
       0 <= nb0 <= 7 -> 0 <= nb1 <= 7 -> 0 <= nb2 <= 7 -> 0 <= nb3 <= 7 ->
       5 <= d0 <= 10 -> 5 <= d1 <= 10 -> 5 <= d2 <= 10 -> 5 <= d3 <= 10 ->
       evt psegs Q (MS (mkR b3' sp gp tp (Z_to_bv 64 (IP0 - nb0)) j6' (Z_to_bv 64 (OP2 + d2)) (Z_to_bv 64 DT4) j9' a0
                            b0' b1' j13' (Z_to_bv 64 0x104d0) (Z_to_bv 64 (IP3 - nb3)) (Z_to_bv 64 (IP2 - nb2))
                            (Z_to_bv 64 (IP1 - nb1)) b2' j19' j20' j21' s6 (Z_to_bv 64 0x10380) s8
